if (points.empty() || k == 0) {
        return {};
    }

    std::vector<std::pair<float, size_t>> distances;
    distances.reserve(points.size());

    for (size_t i = 0; i < points.size(); ++i) {
        float dx = points[i].x - searchPoint.x;
        float dy = points[i].y - searchPoint.y;
        float dz = points[i].z - searchPoint.z;
        float distSq = dx * dx + dy * dy + dz * dz;
        distances.push_back({distSq, i});
    }

    size_t numNeighbors = std::min(k, points.size());
    std::partial_sort(distances.begin(), distances.begin() + numNeighbors, distances.end());

    std::vector<size_t> result;
    result.reserve(numNeighbors);
    for (size_t i = 0; i < numNeighbors; ++i) {
        result.push_back(distances[i].second);
    }

    return result;

